-- Default LSP settings.
--
-- Do not edit this file to change them. Either pass the same shape to setup():
--
--		require('genja').setup({ lsp = { enabled = { php = true } } })
--
-- or, for one machine only, put a lua/genja/lsp/local.lua in your Neovim
-- config directory. It has the same shape, is merged over everything else,
-- and is meant to stay out of git. Example:
--
--		return { enabled = { php = true, python = false } }
--		return { enabled = { php = true, powershell = false } }

---Keys are file names in lua/genja/lang/; a language you add there works too.
---@class genja.lsp.Enabled: { [string]: boolean }
---@field bash? boolean
---@field c_cpp? boolean
---@field gitconfig? boolean
---@field go? boolean
---@field json? boolean
---@field lua? boolean
---@field make? boolean
---@field php? boolean
---@field powershell? boolean
---@field python? boolean
---@field sshconfig? boolean
---@field typescript? boolean
---@field vim? boolean

---@class genja.lsp.PhpactorWsl
---@field distro? string wsl.exe -d <distro>; nil: the default distro
---@field install? boolean install PHP and phpactor in the distro when missing

---@class genja.lsp.Opts
---@field enabled? genja.lsp.Enabled languages to turn on
---@field mason? MasonSettings passed to require('mason').setup()
---@field diagnostics? vim.diagnostic.Opts|false passed to vim.diagnostic.config()
---@field phpactor_wsl? genja.lsp.PhpactorWsl

---@type genja.lsp.Opts
return {
	-- Keys are file names in lua/genja/lang/ sans «.lua»
	-- false or absent: the language is skipped and nothing is installed for it.
	-- i.e you need to add a lang-key here after installing a new language
	enabled = {
		-- shells
		powershell = false,
		bash = true,
		lua = true,
		vim = true,
		make = false,
		gitconfig = true, -- no server: git's own parse errors (ftplugin/gitconfig.lua)
		sshconfig = true, -- no server: ssh's own parse errors (ftplugin/sshconfig.lua)

		-- langs
		typescript = false,
		c_cpp = false,
		go = false,
		json = true,

		-- scrapt itropretor langs
		python = false,
		php = false,
	},

	-- Windows: phpactor runs inside WSL (lua/genja/lang/php.lua, doc/phpactor-wsl.md).
	phpactor_wsl = {
		distro = nil, -- wsl.exe -d <distro>; nil: the default distro (`wsl -l -v`)
		install = true, -- install PHP and phpactor in the distro when missing
	},

	-- Passed to require('mason').setup().
	mason = {
		ui = { border = 'double' },
	},

	-- Passed to vim.diagnostic.config(). false: leave diagnostics alone.
	-- Neovim 0.11 turned inline virtual text off by default.
	-- Quieter alternatives are in the README.
	diagnostics = {
		virtual_text = true,
		severity_sort = true,
	},
}
